on conflict (id) do update set slug = excluded.slug, label = excluded.label;

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  lat = excluded.lat,
  lng = excluded.lng,
  address = excluded.address,
  hours_description = excluded.hours_description,
  opening_hours = excluded.opening_hours,
  amenities = excluded.amenities,
  busy_score = excluded.busy_score,
  atmosphere_score = excluded.atmosphere_score,
  is_active = excluded.is_active,
  last_updated = excluded.last_updated;

delete from location_tags where location_id in ('college-library', 'memorial-library', 'steenbock-library', 'wendt-commons', 'memorial-union', 'memorial-union-lower-level', 'union-south', 'student-activity-center', 'gordons-upstairs', 'historical-society', 'wid', 'sohe', 'valentia', 'aldos-cafe', 'peets-union-south', 'peets-memorial-union', 'starbucks-smith', 'colectivo-state', 'starbucks-state', 'fair-trade-coffee', 'sencha-tea-bar', 'michelangelos', 'barriques-monroe', 'barriques-capitol', 'bradburys', 'lakeside-street-coffee', 'indie-coffee', 'leopolds', 'ancora-king', 'wonderstate', 'forage-kitchen', 'library-mall-food-carts', 'rising-sons', 'ians-pizza', 'bassett-brunch-club', 'library-cafe', 'babcock-dairy', 'slow-food-uw', 'marigold-kitchen', 'la-brioche', 'lucille', 'los-gemelos', 'bloom-bake-shop', 'canteen', 'chocolate-shoppe', 'old-fashioned', 'montys-diner', 'lazy-janes', 'red-sushi', 'maharani', 'pizza-brutta', 'glass-nickel', 'overture-center', 'barrymore', 'the-sylvee', 'majestic', 'orpheum', 'breese-stevens', 'the-marquee', 'wheelhouse-studios', 'state-capitol', 'farmers-market', 'room-of-ones-own', 'mystery-to-me', 'lake-city-books', 'ink-and-ivy', 'madison-greenhouse-store', 'green-life-trading', 'little-luxuries', 'anthology', 'olbrich-gardens', 'allen-centennial-garden', 'uw-arboretum', 'james-madison-park', 'tenney-park', 'wingra-park', 'brittingham-park', 'picnic-point');

